// Input 0 = /stats/monthly, Input 1 = /orders (appendInputs merge)
const stats = $input.all()[0].json;
const { month, orders, top_products, web_interactions } = stats;

// Formatear revenue en ARS
const revenueNum = orders.revenue || 0;
const revenue = new Intl.NumberFormat('es-AR', {
  style: 'currency',
  currency: 'ARS',
  minimumFractionDigits: 2
}).format(revenueNum);

// Top 3 productos
const top3 = (top_products || []).slice(0, 3);

// Interacciones web como mapa
const interMap = {};
(web_interactions || []).forEach(i => { interMap[i.tipo] = i.count; });
const vistas = interMap['vista'] || 0;
const carritos = interMap['carrito'] || 0;
const compras = interMap['compra'] || 0;
const conversionRate = vistas > 0 ? ((compras / vistas) * 100).toFixed(1) : '0.0';

// --- HTML REPORT ---
const topProductsHtml = top3.map((p, idx) =>
  `<tr><td><strong>#${idx + 1}</strong></td><td>${p.nombre}</td><td>${p.sku}</td><td style="text-align:center">${p.units_sold}</td></tr>`
).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Reporte Mensual Golden Harvest — ${month}</title>
  <style>
    body { font-family: Arial, sans-serif; max-width: 720px; margin: 0 auto; padding: 24px; color: #333; background: #fafafa; }
    .header { background: #8B6914; color: white; padding: 20px 24px; border-radius: 8px 8px 0 0; }
    .header h1 { margin: 0; font-size: 22px; }
    .header p { margin: 4px 0 0; font-size: 14px; opacity: 0.85; }
    .section { background: white; border: 1px solid #e0d8c8; padding: 20px 24px; margin-top: 12px; border-radius: 6px; }
    .section h2 { margin: 0 0 14px; color: #5a3e1b; font-size: 16px; border-bottom: 1px solid #e0d8c8; padding-bottom: 8px; }
    .kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 0; }
    .kpi { background: #f5f0e8; border-radius: 6px; padding: 14px; text-align: center; }
    .kpi .value { font-size: 24px; font-weight: bold; color: #8B6914; }
    .kpi .label { font-size: 12px; color: #666; margin-top: 4px; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    th { background: #f5f0e8; text-align: left; padding: 8px 10px; color: #5a3e1b; }
    td { padding: 8px 10px; border-bottom: 1px solid #f0ebe0; }
    .footer { font-size: 12px; color: #999; text-align: center; margin-top: 20px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>📊 Reporte Mensual — Golden Harvest S.A.</h1>
    <p>Período: ${month}</p>
  </div>

  <div class="section">
    <h2>Resumen de Pedidos</h2>
    <div class="kpi-grid">
      <div class="kpi"><div class="value">${orders.total_orders || 0}</div><div class="label">Pedidos totales</div></div>
      <div class="kpi"><div class="value">${orders.unique_customers || 0}</div><div class="label">Clientes únicos</div></div>
      <div class="kpi"><div class="value">${revenue}</div><div class="label">Facturación total</div></div>
    </div>
  </div>

  <div class="section">
    <h2>Top 3 Productos más Vendidos</h2>
    <table>
      <tr><th>Pos.</th><th>Producto</th><th>SKU</th><th style="text-align:center">Unidades</th></tr>
      ${topProductsHtml}
    </table>
  </div>

  <div class="section">
    <h2>Interacciones Web</h2>
    <table>
      <tr><th>Métrica</th><th>Cantidad</th></tr>
      <tr><td>Vistas de producto</td><td>${vistas}</td></tr>
      <tr><td>Agregados al carrito</td><td>${carritos}</td></tr>
      <tr><td>Compras completadas</td><td>${compras}</td></tr>
      <tr><td>Tasa de conversión (vista a compra)</td><td>${conversionRate}%</td></tr>
    </table>
  </div>

  <p class="footer">Reporte generado el ${new Date().toLocaleDateString('es-AR', { day:'2-digit', month:'long', year:'numeric' })} · Golden Harvest S.A. · Sistema n8n</p>
</body>
</html>`;

// --- TEXTO PLANO ---
const topProductsTxt = top3.map((p, i) =>
  `  ${i+1}. ${p.nombre} (${p.sku}): ${p.units_sold} unidades`
).join('\n');

const report_text = [
  '====================================================',
  '  REPORTE MENSUAL — GOLDEN HARVEST S.A.',
  `  Período: ${month}`,
  '====================================================',
  '',
  'RESUMEN DE PEDIDOS',
  `  Pedidos totales:   ${orders.total_orders || 0}`,
  `  Clientes únicos:   ${orders.unique_customers || 0}`,
  `  Facturación total: ${revenue}`,
  '',
  'TOP 3 PRODUCTOS MÁS VENDIDOS',
  topProductsTxt,
  '',
  'INTERACCIONES WEB',
  `  Vistas de producto:        ${vistas}`,
  `  Agregados al carrito:      ${carritos}`,
  `  Compras completadas:       ${compras}`,
  `  Tasa de conversión:        ${conversionRate}%`,
  '',
  '====================================================',
  `Generado automáticamente por n8n — ${new Date().toISOString()}`,
  '===================================================='
].join('\n');

// Log para verificación en el panel de ejecución de n8n
console.log('=== REPORTE MENSUAL GOLDEN HARVEST ===');
console.log(report_text);
console.log('=== FIN DEL REPORTE ===');

return [{ json: { report_html: html, report_text, month } }];
